// Resolve the two recurrent generated/list conflicts during a Git merge.
// Run from the repository root while the merge is stopped:
//   node tools/resolve-generated-merge.mjs
// Or start a no-commit merge and resolve the generated conflicts as part of it:
//   node tools/resolve-generated-merge.mjs --merge=origin/topic
// Hand-written marks rows are three-way merged; only MARK is regenerated by tells.
// Any conflicting hand-written change remains unresolved for a human to inspect.
import { execFileSync, spawnSync } from 'node:child_process';
import assert from 'node:assert/strict';
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const MARKS = 'src/marks.js', CHECK = 'tools/check.mjs';
const marker = '/* GENERATED_MERGE_PLACEHOLDER */';
const markBlock = /\/\* MARK:BEGIN \*\/[\s\S]*?\/\* MARK:END \*\//;
const checkList = /for \(const t of \[(?<names>(?:'[^']+'(?:, )?)+)\]\) if \(take\(t\)\) results\.push\(run\(t, process\.execPath, \['tools\/' \+ t \+ '\.mjs'\]\)\);/;
const git = (...args) => execFileSync('git', args, { encoding: 'utf8' });
const stage = (n, path) => git('show', `:${n}:${path}`);
const unmerged = () => new Set(git('ls-files', '-u').split(/\r?\n/).filter(Boolean).map(line => line.split('\t')[1]));
const namesOf = text => {
  const m = text.match(checkList);
  if (!m) throw new Error('tools/check.mjs test list was not found; inspect the conflict manually');
  return [...m.groups.names.matchAll(/'([^']+)'/g)].map(x => x[1]);
};
const stripMarks = text => {
  if (!markBlock.test(text)) throw new Error('src/marks.js MARK block was not found');
  return text.replace(markBlock, `/* MARK:BEGIN */\n${marker}\n/* MARK:END */`);
};
const stripCheck = text => text.replace(checkList, marker);

function mergeText(base, ours, theirs) {
  const dir = mkdtempSync(join(tmpdir(), 'bracken-merge-'));
  try {
    const paths = ['ours', 'base', 'theirs'].map(x => join(dir, x));
    [ours, base, theirs].forEach((value, i) => writeFileSync(paths[i], value));
    const r = spawnSync('git', ['merge-file', '-p', ...paths], { encoding: 'utf8' });
    if (r.status !== 0) throw new Error('authored content conflicts; inspect and merge it manually:\n' + (r.stdout || r.stderr || ''));
    return r.stdout;
  } finally { rmSync(dir, { recursive: true, force: true }); }
}

function resolveMarks() {
  const merged = mergeText(stripMarks(stage(1, MARKS)), stripMarks(stage(2, MARKS)), stripMarks(stage(3, MARKS)));
  // tools/tells.mjs imports marks.js, so first give it valid authored tables with either side's generated MARK.
  const ours = stage(2, MARKS).match(markBlock)?.[0];
  if (!ours) throw new Error('ours lacks a generated MARK block');
  writeFileSync(MARKS, merged.replace(`/* MARK:BEGIN */\n${marker}\n/* MARK:END */`, ours));
  const wrote = spawnSync(process.execPath, ['tools/tells.mjs', '--write'], { encoding: 'utf8' });
  if (wrote.status !== 0) throw new Error('tells --write failed; src/marks.js was left for inspection:\n' + (wrote.stdout || '') + (wrote.stderr || ''));
  const checked = spawnSync(process.execPath, ['tools/tells.mjs'], { encoding: 'utf8' });
  if (checked.status !== 0) throw new Error('regenerated marks failed tells; src/marks.js was left for inspection:\n' + (checked.stdout || '') + (checked.stderr || ''));
  git('add', MARKS);
  console.log('resolved src/marks.js: authored tables merged, MARK regenerated, tells green');
}

function resolveCheck() {
  const [base, ours, theirs] = [1, 2, 3].map(n => stage(n, CHECK));
  const names = [...new Set([...namesOf(ours), ...namesOf(theirs)])];
  const merged = mergeText(stripCheck(base), stripCheck(ours), stripCheck(theirs));
  if (!merged.includes(marker)) throw new Error('tools/check.mjs list placeholder was lost');
  const list = `for (const t of [${names.map(n => `'${n}'`).join(', ')}]) if (take(t)) results.push(run(t, process.execPath, ['tools/' + t + '.mjs']));`;
  writeFileSync(CHECK, merged.replace(marker, list));
  const checked = spawnSync(process.execPath, ['--check', CHECK], { encoding: 'utf8' });
  if (checked.status !== 0) throw new Error('merged check list failed syntax; tools/check.mjs was left for inspection:\n' + checked.stderr);
  git('add', CHECK);
  console.log(`resolved tools/check.mjs: ${names.length} test names in the union, syntax green`);
}

if (process.argv.includes('--selftest')) {
  const base = `head\n/* MARK:BEGIN */\nexport const MARK = { old: 1 };\n/* MARK:END */\nhand\n`;
  const ours = base.replace('old: 1', 'ours: 1').replace('head', 'ours-head');
  const theirs = base.replace('old: 1', 'theirs: 1').replace('hand', 'theirs-hand');
  const merged = mergeText(stripMarks(base), stripMarks(ours), stripMarks(theirs));
  assert(merged.includes('ours-head') && merged.includes('theirs-hand') && merged.includes(marker));
  const list = ns => `for (const t of [${ns.map(n => `'${n}'`).join(', ')}]) if (take(t)) results.push(run(t, process.execPath, ['tools/' + t + '.mjs']));`;
  const a = list(['tells', 'alpha']), b = list(['tells', 'beta']);
  assert.equal(stripCheck(a), marker);
  assert.deepEqual([...new Set([...namesOf(a), ...namesOf(b)])], ['tells', 'alpha', 'beta']);
  console.log('resolve-generated-merge selftest: generated block stripped; authored edits merged; check names unioned');
  process.exit(0);
}

const mergeRef = process.argv.find(a => a.startsWith('--merge='))?.slice(8);
if (mergeRef) {
  if (unmerged().size) throw new Error('a merge is already stopped; resolve it before starting another');
  const result = spawnSync('git', ['merge', '--no-commit', '--no-ff', mergeRef], { encoding: 'utf8' });
  if (result.stdout) process.stdout.write(result.stdout);
  if (result.stderr) process.stderr.write(result.stderr);
  if (result.status !== 0 && !unmerged().size) throw new Error(`merge did not start or failed without conflicts (exit ${result.status})`);
}
const paths = unmerged();
if (!paths.has(MARKS) && !paths.has(CHECK)) { console.log('no generated marks or check-list conflict is pending'); process.exit(0); }
try {
  if (paths.has(MARKS)) resolveMarks();
  if (paths.has(CHECK)) resolveCheck();
  const left = unmerged();
  console.log(left.size ? `other conflicts remain: ${[...left].join(', ')}` : 'generated merge conflicts resolved; run the full gate before committing');
} catch (error) { console.error('STOPPED: ' + error.message); process.exitCode = 1; }
